INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('16', '16', 'ARC-016', 'Toko Tamiang Confectionery', 'Toko Tamiang Confectionery', 'Kuliner', 'Kue (Mooncake/Kue Bulan)', 'Situs', 'Emas (Kuliner & Gastronomi)', '#D97706', 'Tradisi Kuliner Tionghoa Medan', 'Kawasan Toko Tamiang Confectionery, Kota Medan', 'Gang Buntu', 'Kec. Medan Timur', 'Kota Medan', '3.5954895', '98.6857713', 'Situs gastronomi dan kuliner legendaris Tionghoa di Kota Medan untuk kategori Kue (Mooncake/Kue Bulan) (Toko Tamiang Confectionery). Menjadi bagian dari adaptasi panjang budaya kuliner Tionghoa dalam ruang kota multikultural Medan (Sumber: Wikipedia).', 'Wikipedia', 'https://en.wikipedia.org/wiki/Mooncake', 'https://maps.app.goo.gl/yFBVgFbyDKxwmHeU6', '/images/sites/kuliner_mooncake.jpg', '[\"\\/images\\/sites\\/kuliner_mooncake.jpg\",\"\\/images\\/sites\\/site_016_a.svg\",\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_016_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('17', '17', 'ARC-017', 'Vihara Setia Budi', 'Vihara Setia Budi', 'Tempat Ibadah', 'Vihara', 'Rumah Ibadah', 'Merah (Tempat Ibadah)', '#B91C1C', '1882', 'Jl. Irian Barat No.36, Gg. Buntu, Kec. Medan Tim., Kota Medan, Sumatera Utara 20212', 'Gang Buntu', 'Kec. Medan Timur', 'Kota Medan', '3.5882821', '98.6820028', 'Didirikan pada tahun 1882 (dikenal juga sebagai Kwan Tie Miau), merupakan salah satu kelenteng/vihara bersejarah tertua di kawasan Gang Buntu, Medan Timur, yang menjadi pusat spiritual dan titik temu masyarakat Tionghoa Medan.', 'Arsip Kajian & Referensi Situs', 'https://www.wihara.org/listings/kwan-tie-miau/149', 'https://maps.app.goo.gl/q41HPy46awDRuuL19', '/images/sites/vihara_gunung_timur.jpg', '[\"\\/images\\/sites\\/vihara_gunung_timur.jpg\",\"\\/images\\/sites\\/site_017_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_017_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('18', '18', 'ARC-018', 'Siu San Keng Temple (寿山宫)', 'Siu San Keng Temple (寿山宫)', 'Tempat Ibadah', 'Vihara', 'Rumah Ibadah', 'Merah (Tempat Ibadah)', '#B91C1C', '1890', 'PMMG+73M, Jl. Syahbudin Yatim, Pekan Labuhan, Kec. Medan Labuhan, Kota Medan, Sumatera Utara 20253', 'Pekan Labuhan', 'Kec. Medan Labuhan', 'Kota Medan', '3.7332193', '98.6751814', 'Berdiri pada tahun 1890 dan merupakan vihara tertua di kota Medan. Lokasinya berdekatan dengan Masjid Raya Al-Osmani sehingga menjadi simbol keharmonisan antarumat beragama pada masa kolonial Belanda. Di area vihara juga terdapat mata air yang disebut tidak pernah kering meski musim kemarau panjang.', 'Arsip Kajian & Referensi Situs', 'https://medanlabuhan.medan.go.id/menu/Potensi/Vihara.html', 'https://maps.app.goo.gl/EwZxoDW8AoPSGsEv6', '/images/sites/vihara_gunung_timur.jpg', '[\"\\/images\\/sites\\/vihara_gunung_timur.jpg\",\"\\/images\\/sites\\/site_018_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_018_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('19', '19', 'ARC-019', 'Vihara Gunung Timur', 'Vihara Gunung Timur', 'Tempat Ibadah', 'Vihara', 'Rumah Ibadah', 'Merah (Tempat Ibadah)', '#B91C1C', '1930-1960, 1962', 'Jl. Hang Tuah No.16, Madras Hulu, Kec. Medan Polonia, Kota Medan, Sumatera Utara 20151', 'Madras Hulu', 'Kec. Medan Polonia', 'Kota Medan', '3.5780597', '98.6689928', 'Didirikan pada periode 1930–1962 di tepi Sungai Babura (Jl. Hang Tuah), Vihara Gunung Timur adalah kelenteng Taoisme dan Buddha terbesar di Kota Medan serta menjadi pusat perayaan Imlek dan Cap Go Meh.', 'Arsip Kajian & Referensi Situs', 'https://medantourism.medan.go.id/destinasi_wisata/public/detail/14', 'https://maps.app.goo.gl/orbgMRE6J8esZRWL9', '/images/sites/vihara_gunung_timur.jpg', '[\"\\/images\\/sites\\/vihara_gunung_timur.jpg\",\"\\/images\\/sites\\/site_019_a.svg\",\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_019_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('20', '20', 'ARC-020', 'Vihara Borobudur', 'Vihara Borobudur', 'Tempat Ibadah', 'Vihara', 'Rumah Ibadah', 'Merah (Tempat Ibadah)', '#B91C1C', '1963', 'Jl. Imam Bonjol No.21, Hamdan, Kec. Medan Maimun, Kota Medan, Sumatera Utara 20151', 'Hamdan', 'Kec. Medan Maimun', 'Kota Medan', '3.5813014', '98.6769887', 'Menjadi lokasi Hari Waisak gabungan pertama di Medan pada 1967, jauh sebelum Waisak ditetapkan sebagai Hari Libur Nasional pada 1983.', 'Arsip Kajian & Referensi Situs', 'https://www.viharaborobudur.org/home/tentang.html', 'https://maps.app.goo.gl/UvzVt8xJKhVyBoqN6', '/images/sites/vihara_gunung_timur.jpg', '[\"\\/images\\/sites\\/vihara_gunung_timur.jpg\",\"\\/images\\/sites\\/site_020_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_020_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('21', '21', 'ARC-021', 'Maha Vihara Maitreya', 'Maha Vihara Maitreya', 'Tempat Ibadah', 'Vihara', 'Rumah Ibadah', 'Merah (Tempat Ibadah)', '#B91C1C', '2008', 'Medan, Jl. Cemara Asri Boulevard Raya No.8, Medan Estate, Kec. Percut Sei Tuan, Kabupaten Deli Serdang, Sumatera Utara 20371', 'Medan Estate', 'Kec. Percut Sei Tuan', 'Kabupaten Deli Serdang', '3.6379313', '98.7013063', 'Diresmikan pada tahun 2008 di kawasan Cemara Asri, merupakan salah satu vihara Buddha aliran Maitreya terbesar di Indonesia dengan arsitektur megah yang memadukan estetika tradisional Tionghoa dan tata ruang modern.', 'Arsip Kajian & Referensi Situs', 'https://mahaviharamaitreya.org/sejarah-pendirian/', 'https://maps.app.goo.gl/PYC8uJfb4KRqmhk6A', '/images/sites/vihara_gunung_timur.jpg', '[\"\\/images\\/sites\\/vihara_gunung_timur.jpg\",\"\\/images\\/sites\\/site_021_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_021_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('22', '22', 'ARC-022', 'Museum Situs Kota Cina', 'Museum Situs Kota Cina', 'Tempat Ibadah', 'Kelenteng', 'Museum China', 'Merah (Tempat Ibadah)', '#B91C1C', 'Abad ke-19 – ke-20', 'PMF4+5PV, Jl. Kota Cina, Paya Pasir, Kec. Medan Marelan, Kota Medan, Sumatera Utara 20254', 'Paya Pasir', 'Kec. Medan Marelan', 'Kota Medan', '3.7229863', '98.6568084', 'Dibangun pada 2008 oleh sejarawan Ichwan Azhari di Paya Pasir, Medan Marelan. Lokasinya merupakan dermaga dagang internasional penting di Pantai Timur Sumatera abad ke-11 hingga ke-14. Koleksinya mencakup keramik Dinasti Song-Yuan, mata uang kuno, arca, dan struktur reruntuhan candi bata kuno.', 'Arsip Kajian & Referensi Situs', 'https://journals.openedition.org/archipel/7197', 'https://maps.app.goo.gl/7TcwrRT3GnsCDCq1A', '/images/sites/vihara_gunung_timur.jpg', '[\"\\/images\\/sites\\/vihara_gunung_timur.jpg\",\"\\/images\\/sites\\/site_022_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_022_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('23', '23', 'ARC-023', 'Chinese Temple Jit Sien Nio Nio', 'Chinese Temple Jit Sien Nio Nio', 'Tempat Ibadah', 'Kelenteng', 'Rumah Ibadah', 'Merah (Tempat Ibadah)', '#B91C1C', 'Abad ke-19 – ke-20', 'Jl. H. Adam Malik No.7, Sekip, Kec. Medan Petisah, Kota Medan, Sumatera Utara 20231', 'Sekip', 'Kec. Medan Petisah', 'Kota Medan', '3.5948608', '98.6687901', 'Memuja Qishi Niangniang (Tujuh Suci/Bidadari). Dalam mitos yang dicantumkan, para saudari Zhinu merawat anak-anak di bumi secara gaib sehingga tempat ini menjadi simbol pelindung anak serta penasihat jodoh.', 'Arsip Kajian & Referensi Situs', 'https://jalan-indonesia.openalfa.com/jalan-jalan/jalan-glugur-by-pass-medan', 'https://maps.app.goo.gl/z3ocM8dzSRVfn7iaA', '/images/sites/vihara_gunung_timur.jpg', '[\"\\/images\\/sites\\/vihara_gunung_timur.jpg\",\"\\/images\\/sites\\/site_023_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_023_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('24', '24', 'ARC-024', 'Vihara Mahasampatti', 'Vihara Mahasampatti', 'Tempat Ibadah', 'Vihara', 'Rumah Ibadah', 'Merah (Tempat Ibadah)', '#B91C1C', '1994', 'Jl. Pajang No.1-17, Sei Rengas Permata, Kec. Medan Area, Kota Medan, Sumatera Utara 20211', 'Sei Rengas I', 'Kec. Medan Area', 'Kota Medan', '3.5824139', '98.6937201', 'Merupakan vihara mazhab Theravāda pertama di Kota Medan dan Provinsi Sumatera Utara yang berada di bawah pembinaan Saṅgha Theravāda Indonesia (STI) dan MAGABUDHI.', 'Arsip Kajian & Referensi Situs', 'https://donasi.viharamahasampatti.or.id/page/sejarah', 'https://maps.app.goo.gl/PCx5FZnzLLBvAafz9', '/images/sites/vihara_gunung_timur.jpg', '[\"\\/images\\/sites\\/vihara_gunung_timur.jpg\",\"\\/images\\/sites\\/site_024_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_024_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('25', '25', 'ARC-025', 'Masjid Lama Gang Bengkok', 'Masjid Lama Gang Bengkok', 'Tempat Ibadah', 'Masjid', 'Rumah Ibadah', 'Merah (Tempat Ibadah)', '#B91C1C', '1874 (surau), 1887 (masjid)', 'Jl. Mesjid No.62, Kesawan, Kec. Medan Bar., Kota Medan, Sumatera Utara 20212', 'Kesawan', 'Kec. Medan Barat', 'Kota Medan', '3.5866762', '98.6780170', 'Merupakan masjid pertama yang bernuansa Tionghoa di Medan dan salah satu yang tertua. Dalam file disebut didirikan oleh Tjong A Fie pada 1874 atau 1885.', 'Arsip Kajian & Referensi Situs', 'https://jurnal.medanresourcecenter.org/index.php/HIJ/article/view/1475', 'https://maps.app.goo.gl/UjbzodUoPJ1Knk919', '/images/sites/masjid_gang_bengkok.jpg', '[\"\\/images\\/sites\\/masjid_gang_bengkok.jpg\",\"\\/images\\/sites\\/site_025_a.svg\",\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_025_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('26', '26', 'ARC-026', 'KELENTENG HOK SAN TUAH (Hok Tek Cin Sin - Tua Pek Kong)', 'KELENTENG HOK SAN TUAH (Hok Tek Cin Sin - Tua Pek Kong)', 'Tempat Ibadah', 'Kelenteng', 'Rumah Ibadah', 'Merah (Tempat Ibadah)', '#B91C1C', 'Abad ke-19 – ke-20', 'Gg. Efrata No.120, Sei Agul, Kec. Medan Bar., Kota Medan, Sumatera Utara 20117', 'Sei Agul', 'Kec. Medan Barat', 'Kota Medan', '3.6021932', '98.6525908', 'Mempertahankan gaya tradisional Tionghoa dengan atap melengkung, ornamen naga, dan pilar merah yang melambangkan keberuntungan. Nama Hok, San, dan Tuah dijelaskan sebagai berkah, gunung, dan kebajikan.', 'Arsip Kajian & Referensi Situs', 'Belum ditemukan artikel sejarah yang secara khusus membahas kelenteng ini.', 'https://maps.app.goo.gl/1MhieJPDED5Hxoep7', '/images/sites/vihara_gunung_timur.jpg', '[\"\\/images\\/sites\\/vihara_gunung_timur.jpg\",\"\\/images\\/sites\\/site_026_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_026_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
