INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('49', '49', 'ARC-049', 'Kuburan Kedai Durian an Liu Jen Kuang', 'Kuburan Kedai Durian an Liu Jen Kuang', 'Pemakaman', 'Makam Individu', 'Titik Makam', 'Ungu (Pemakaman & Makam)', '#6D28D9', 'Abad ke-19 – ke-20', 'Jl. Sejati No.8A, Mekar Sari, Kec. Deli Tua, Kabupaten Deli Serdang, Sumatera Utara 20355', 'Mekar Sari', 'Kec. Deli Tua', 'Kabupaten Deli Serdang', '3.5135743', '98.6928758', 'Lahan disebut awalnya disediakan perkebunan tembakau Deli atau perkumpulan sosial Tionghoa untuk menguburkan imigran dan kuli kontrak Tionghoa yang meninggal pada masa kolonial.', 'Inventarisasi Pemakaman Tionghoa Medan', '', 'https://maps.app.goo.gl/rHTrNGo696EH9NxB7', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_049_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_049_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('50', '50', 'ARC-050', 'Kuburan Kedai Durian alm. Yang Ru Qin', 'Kuburan Kedai Durian alm. Yang Ru Qin', 'Pemakaman', 'Makam Individu', 'Titik Makam', 'Ungu (Pemakaman & Makam)', '#6D28D9', 'Abad ke-19 – ke-20', 'GM8Q+X5W, Jl. Kp. Banten, Suka Makmur, Kec. Deli Tua, Kabupaten Deli Serdang, Sumatera Utara', 'Suka Makmur', 'Kec. Deli Tua', 'Kabupaten Deli Serdang', '3.5174844', '98.6879598', 'Merupakan lokasi pekuburan leluhur yang luas; rincian khusus mengenai tanggal pendirian dan kisah alm. Yang Ru Qin disebut umumnya diketahui keluarga/keturunannya.', 'Inventarisasi Pemakaman Tionghoa Medan', '', 'https://maps.app.goo.gl/8SjrkT2NgXcXsRZs9', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_050_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_050_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('51', '51', 'ARC-051', 'Kuburan Massal Kwong Tong Kong Soh & Penanganan Malaria', 'Kuburan Massal Kwong Tong Kong Soh & Penanganan Malaria', 'Pemakaman', 'Pemakaman Tionghoa', 'Titik Makam', 'Ungu (Pemakaman & Makam)', '#6D28D9', 'Abad ke-19 – ke-20', 'GM8Q+X5W, Jl. Kp. Banten, Suka Makmur, Kec. Deli Tua, Kabupaten Deli Serdang, Sumatera Utara', 'Suka Makmur', 'Kec. Deli Tua', 'Kabupaten Deli Serdang', '3.5176432', '98.6882717', 'Kompleks pemakaman massal ini memiliki dinamika sejarah yang sangat unik, terutama berkaitan dengan sanitasi kota Medan pada masa lampau memiliki kaitan erat dengan penanganan wabah malaria pada era kolonial Belanda abad ke-20.', 'Inventarisasi Pemakaman Tionghoa Medan', '', 'https://maps.app.goo.gl/kyrKBcrDP8gVvGvLA', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_051_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_051_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('52', '52', 'ARC-052', 'Eks Kuburan Cina Petisah', 'Eks Kuburan Cina Petisah', 'Pemakaman', 'Bekas Pemakaman', 'Titik Makam', 'Ungu (Pemakaman & Makam)', '#6D28D9', '1901', 'Jl. Iskandar Muda No.143, Sei Sikambing D, Kec. Medan Petisah, Kota Medan, Sumatera Utara 20111', 'Sei Sikambing D', 'Kec. Medan Petisah', 'Kota Medan', '3.5902398', '98.6611705', 'Berdasarkan catatan dan batu prasasti sejarah, kompleks pemakaman ini didirikan sekitar tahun 1879 dengan luas mencapai puluhan hektare (dikelola oleh Hok Kian Hwee Koan). Pemakaman ini kemudian mulai dibongkar dan dipindahkan secara bertahap sekitar tahun 1968 hingga awal 1980-an oleh pemerintah kota bekerja sama dengan pihak pengembang/militer untuk penataan kota. Kemudian dibangun Medan Plaza pada tahun 1982/1983.', 'Inventarisasi Pemakaman Tionghoa Medan', '', 'https://maps.app.goo.gl/q1QXThngnfE7YEL29', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_052_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_052_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('53', '53', 'ARC-053', 'Kuburan Huang Chun Xin', 'Kuburan Huang Chun Xin', 'Pemakaman', 'Makam Individu', 'Titik Makam', 'Ungu (Pemakaman & Makam)', '#6D28D9', 'Abad ke-19 – ke-20', 'GMCR+PJP, Unnamed Road, Kedai Durian, Medan Johor, Medan City, North Sumatra 20147', 'Kedai Durian', 'Kec. Medan Johor', 'Kota Medan', '3.5218263', '98.6915716', 'Komplek pemakaman Tionghoa di Kedai Durian dikelola oleh Yayasan Budi Luhur Kedai Durian yang terletak di Jalan Stasiun, Kelurahan Kedai Durian, Kecamatan Medan Johor. Setiap tahun menjelang bulan April atau sesuai penanggalan Lunar, ribuan keluarga Tionghoa dari berbagai daerah (termasuk luar kota seperti Jakarta dan Bandung) memadati kompleks ini untuk menggelar ritual Cheng Beng (membersihkan makam dan menghormati leluhur).', 'Inventarisasi Pemakaman Tionghoa Medan', '', 'https://maps.app.goo.gl/ifm4Y7hF5oFxRdKh8', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_053_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_053_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('54', '54', 'ARC-054', 'Rumah Tjong A Fie (Tjong A Fie Mansion)', 'Rumah Tjong A Fie (Tjong A Fie Mansion)', 'Perkampungan & Rumah Bersejarah', 'Rumah Tinggal Tokoh Sejarah', 'Perkampungan', 'Hijau (Perkampungan & Ruang Hidup)', '#15803D', '1890-1900', 'Jl. Jend. Ahmad Yani No.105, Kesawan, Kec. Medan Bar., Kota Medan, Sumatera Utara 20111', 'Kesawan', 'Kec. Medan Barat', 'Kota Medan', '3.5856772', '98.6808640', 'Rumah bersejarah dua lantai yang dibangun oleh Kapitan Tjong A Fie pada 1890–1900 di kawasan Kesawan. Arsitekturnya memadukan gaya Tionghoa, Melayu, dan Art Deco Eropa sebagai monumen hidup toleransi dan sejarah Kota Medan.', 'Kajian Ruang Hidup & Perkampungan', '', 'https://maps.app.goo.gl/QLe78orPAV3t5z178', '/images/sites/tjong_a_fie_mansion.jpg', '[\"\\/images\\/sites\\/tjong_a_fie_mansion.jpg\",\"\\/images\\/sites\\/site_054_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_054_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('55', '55', 'ARC-055', 'Rumah dan usaha Law Ah Yok di kawasan Sukaramai', 'Rumah dan usaha Law Ah Yok di kawasan Sukaramai', 'Perkampungan & Rumah Bersejarah', 'Rumah Tinggal dan Bangunan Usaha', 'Perkampungan', 'Hijau (Perkampungan & Ruang Hidup)', '#15803D', 'Abad ke-19 – ke-20', 'Sukaramai, Sumatera Utara, Indonesia', 'Sukaramai I', 'Kec. Medan Area', 'Kota Medan', '3.5798200', '98.7012400', 'Kawasan yang dulunya dikenal sebagai pemukiman kumuh atau ghetto bagi warga Tionghoa miskin ini kemudian berkembang pesat selama lebih dari seabad hingga menjadi cikal bakal kawasan Pecinan (Chinatown) dan area komersial di Medan.', 'Kajian Ruang Hidup & Perkampungan', '', 'https://www.bing.com/maps/search?FORM=HDRSC6&style=r&q=kawasan+sukaramai&cp=3.308339%7E99.440552&lvl=16', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_055_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_055_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('56', '56', 'ARC-056', 'Tjong A Fie', 'Tjong A Fie', 'Tokoh Sejarah', 'Pengusaha & Filantropis — Pengusaha & Kapitan Tionghoa Medan', 'Situs', 'Biru Tua (Pendidikan, Organisasi & Tokoh)', '#1D4ED8', 'Akhir Abad ke-19 – Awal Abad ke-20', 'Medan, Sumatera Utara', 'Kesawan', 'Kec. Medan Barat', 'Kota Medan', '3.5853124', '98.6808351', 'Kapitan Cina Medan, pengusaha perkebunan, bankir, dan dermawan yang berjasa besar membangun infrastruktur Kota Medan serta Masjid Lama Gang Bengkok.', 'Biografi Tokoh Sejarah Tionghoa Medan', 'https://id.wikipedia.org/wiki/Tjong_A_Fie', 'https://id.wikipedia.org/wiki/Tjong_A_Fie', '/images/sites/tokoh_tjong_a_fie.jpg', '[\"\\/images\\/sites\\/tokoh_tjong_a_fie.jpg\",\"\\/images\\/sites\\/site_056_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_056_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('57', '57', 'ARC-057', 'Tjong Yong Hian', 'Tjong Yong Hian', 'Tokoh Sejarah', 'Pengusaha & Filantropis — Kapitan Tionghoa & Filantropis', 'Situs', 'Biru Tua (Pendidikan, Organisasi & Tokoh)', '#1D4ED8', 'Akhir Abad ke-19 – Awal Abad ke-20', 'Medan, Sumatera Utara', 'Petisah Tengah', 'Kec. Medan Petisah', 'Kota Medan', '3.5867374', '98.6690222', 'Mayor Tionghoa Medan, abang Tjong A Fie, pendiri RS Tjie On Djie Jan, Sekolah Dun Pen, dan Jembatan Kebajikan.', 'Biografi Tokoh Sejarah Tionghoa Medan', 'https://id.wikipedia.org/wiki/Tjong_Yong_Hian', 'https://id.wikipedia.org/wiki/Tjong_Yong_Hian', '/images/sites/tokoh_tjong_yong_hian.jpg', '[\"\\/images\\/sites\\/tokoh_tjong_yong_hian.jpg\",\"\\/images\\/sites\\/site_057_a.svg\",\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_057_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('58', '58', 'ARC-058', 'Law Ah Yok', 'Law Ah Yok', 'Tokoh Sejarah', 'Pengusaha & Filantropis — Tokoh Pembangun & Filantropis', 'Situs', 'Biru Tua (Pendidikan, Organisasi & Tokoh)', '#1D4ED8', '1870–1941', 'Medan, Sumatera Utara', 'Sukaramai I', 'Kec. Medan Area', 'Kota Medan', '3.5799788', '98.7015519', 'Tokoh Kantonis Medan (1870–1941) yang membangun kawasan pemukiman khusus warga Tionghoa prasejahtera di Sukaramai Medan. Law Ah Yok adalah seorang tokoh pembangun (builder) sekaligus filantropis asal Kanton (Kantonis) yang hidup sekitar tahun 1870–1941. Ia membangun perkampungan ini khusus sebagai tempat tinggal dan penampungan bagi kaum Tionghoa prasejahtera atau warga Tionghoa miskin yang belum memiliki rumah.', 'Biografi Tokoh Sejarah Tionghoa Medan', 'https://id.wikipedia.org/wiki/Medan', 'https://id.wikipedia.org/wiki/Medan', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_058_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_058_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('59', '59', 'ARC-059', 'Museum Situs Kota Cina', 'Museum Situs Kota Cina', 'Museum & Cagar Budaya', 'Museum Sejarah & Arkeologi', 'Museum China', 'Coklat Kayu (Situs & Cagar Budaya)', '#78350F', '2008', 'Jl. Kota Cina No. 65, Paya Pasir, Medan Marelan', 'Paya Pasir', 'Kec. Medan Marelan', 'Kota Medan', '3.7231451', '98.6571203', 'Dibangun pada 2008 oleh sejarawan Ichwan Azhari. Lokasinya sebelumnya merupakan dermaga dagang internasional penting di Pantai Timur Sumatera abad ke-11 hingga ke-14. Koleksinya mencakup keramik Dinasti Song-Yuan, mata uang kuno, arca, dan struktur reruntuhan candi bata kuno.', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://maps.app.goo.gl/3hdFch2WC9a2rhiZ6', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_059_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_059_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('60', '60', 'ARC-060', 'Jembatan Kebajikan (\"Jembatan Berlian\")', 'Jembatan Kebajikan (\"Jembatan Berlian\")', 'Bangunan Bersejarah', 'Jembatan Bersejarah', 'Situs', 'Coklat Kayu (Situs & Cagar Budaya)', '#78350F', '1916', 'Jl. K.H. Zainul Arifin, Petisah Hulu', 'Petisah Hulu', 'Kec. Medan Baru', 'Kota Medan', '3.5841000', '98.6678520', 'Dibangun pada tahun 1916 oleh Mayor Tjong Yong Hian di atas Sungai Babura (Jl. K.H. Zainul Arifin) sebagai wujud filantropi untuk menghubungkan akses warga kota; menyandang prasasti aksara Tionghoa dan dikenal sebagai Jembatan Berlian.', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://maps.app.goo.gl/zHCrHfxav2chkQUK8', '/images/sites/tokoh_tjong_yong_hian.jpg', '[\"\\/images\\/sites\\/tokoh_tjong_yong_hian.jpg\",\"\\/images\\/sites\\/site_060_a.svg\",\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_060_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('61', '61', 'ARC-061', 'Kawasan Kesawan', 'Kawasan Kesawan', 'Bangunan Bersejarah', 'Kawasan Perdagangan & Pecinan', 'Situs', 'Coklat Kayu (Situs & Cagar Budaya)', '#78350F', 'Akhir abad ke-19–awal abad ke-20', 'Kel. Kesawan, Kec. Medan Barat, Kota Medan, Sumatera Utara', 'Kesawan', 'Kec. Medan Barat', 'Kota Medan', '3.5864326', '98.6795184', 'Koridor kota tua dan pusat niaga bersejarah Kota Medan sejak akhir abad ke-19, tempat deretan ruko (shophouse) bergaya Peranakan Tionghoa-Eropa, Rumah Tjong A Fie, dan Toko Seng Hap berdiri berdampingan.', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://maps.app.goo.gl/sHkfctHrjN6qBCT79', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_061_a.svg\",\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_061_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('62', '62', 'ARC-062', 'Menara Jam Balai Kota Lama', 'Menara Jam Balai Kota Lama', 'Bangunan Bersejarah', 'Menara Jam & Bangunan Pemerintahan', 'Situs', 'Coklat Kayu (Situs & Cagar Budaya)', '#78350F', '1908', 'Persimpangan Jl. Raden Saleh–Kesawan', 'Kesawan', 'Kec. Medan Barat', 'Kota Medan', '3.5904215', '98.6773720', 'Dibangun pada tahun 1908 di persimpangan Jl. Raden Saleh–Kesawan. Jam besar pada menara gedung Balai Kota Lama ini merupakan sumbangan dari saudagar dan Kapitan Tionghoa Tjong A Fie bagi masyarakat Kota Medan.', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://maps.app.goo.gl/17TDg7Ewe689A5zK7', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_062_a.svg\",\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_062_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('63', '63', 'ARC-063', 'Bekas Nam Ang School', 'Bekas Nam Ang School', 'Pendidikan & Lembaga Sosial', 'Sekolah Tionghoa Bersejarah', 'Situs', 'Biru Tua (Pendidikan, Organisasi & Tokoh)', '#1D4ED8', 'Abad ke-19 – ke-20', 'Kel. Sei Rengas I, Kec. Medan Area, Kota Medan, Sumatera Utara', 'Sei Rengas I', 'Kec. Medan Area', 'Kota Medan', '3.5861200', '98.6939100', 'Sekolah Tionghoa historis yang mengalami penutupan pada masa Orde Lama/G30S/PKI. Kini lokasi disebut telah menjadi SMP Negeri 12 Medan.', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://www.google.com/maps/search/?api=1&query=Bekas+Nam+Ang+School%2C+%2C+Medan%2C+Sumatera+Utara', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_063_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_063_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('64', '64', 'ARC-064', 'Bekas Chung Wen School', 'Bekas Chung Wen School', 'Pendidikan & Lembaga Sosial', 'Sekolah Tionghoa Bersejarah', 'Situs', 'Biru Tua (Pendidikan, Organisasi & Tokoh)', '#1D4ED8', '1955-1966', 'Jl. Willem Iskandar, Jl. Pancing Blok Cinta Budaya No.1, Bantan Tim., Kec. Percut Sei Tuan, Kabupaten Deli Serdang, Sumatera Utara 20371', 'Bantan Timur', 'Kec. Percut Sei Tuan', 'Kabupaten Deli Serdang', '3.6004494', '98.7088335', 'Didirikan pada 1955 dan ditutup 1966. Kemudian dihidupkan kembali oleh alumni sebagai Sekolah Cinta Budaya Chongwen pada 2011.', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://maps.app.goo.gl/G5HTAAtgiLfNqrxP9', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_064_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_064_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('65', '65', 'ARC-065', 'Bekas Sekolah Dun Pen', 'Bekas Sekolah Dun Pen', 'Pendidikan & Lembaga Sosial', 'Sekolah Tionghoa Bersejarah', 'Situs', 'Biru Tua (Pendidikan, Organisasi & Tokoh)', '#1D4ED8', '1908', 'Jl. Bilal Ujung No.3/145, Pulo Brayan Darat I, Kec. Medan Tim., Kota Medan, Sumatera Utara 20239', 'Pulo Brayan Darat I', 'Kec. Medan Timur', 'Kota Medan', '3.6229864', '98.6830738', 'Didirikan Tjong Yong Hian dan Tjong A Fie. Dahulu berada di belakang/area Vihara Tian Hou (Mazu), dan kini disebut telah berubah menjadi kawasan Vihara Setia Budi.', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://maps.app.goo.gl/H9T1J3FV4Kjr3CxBA', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_065_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_065_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('66', '66', 'ARC-066', 'Bekas Rumah Sakit Tjie On Djie Jan', 'Bekas Rumah Sakit Tjie On Djie Jan', 'Pendidikan & Lembaga Sosial', 'Rumah Sakit Bersejarah', 'Situs', 'Biru Tua (Pendidikan, Organisasi & Tokoh)', '#1D4ED8', '1890', 'Kawasan Jalan Sambu, Medan', 'Gang Buntu', 'Kec. Medan Timur', 'Kota Medan', '3.5912400', '98.6865200', 'Diinisiasi Tjong Yong Hian dan Tjong A Fie untuk membantu masyarakat kelas bawah, khususnya imigran Tionghoa miskin. Bangunan lama kini tidak tersisa dan lahannya telah menjadi kawasan komersial Jalan Sambu.', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://www.google.com/maps/search/?api=1&query=Bekas+Rumah+Sakit+Tjie+On+Djie+Jan%2C+%2C+Medan%2C+Sumatera+Utara', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_066_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_066_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('67', '67', 'ARC-067', 'Gedung perkumpulan Teochew,Teochiu Huikuan', 'Gedung perkumpulan Teochew,Teochiu Huikuan', 'Organisasi & Perkumpulan', 'Gedung Perkumpulan Masyarakat Tionghoa', 'Situs', 'Biru Tua (Pendidikan, Organisasi & Tokoh)', '#1D4ED8', '2000–2001', 'Jl. Gandhi No.123, Sei Rengas II, Medan Area', 'Sei Rengas II', 'Kec. Medan Area', 'Kota Medan', '3.5911207', '98.6631473', 'Secara keorganisasian, embrio Perhimpunan Teo Chew di Indonesia mulai bangkit secara masif pada tahun 2000–2001 seiring bergulirnya era reformasi. Hal paling unik dan menarik dari situs Gedung Teochew Medan terletak pada sejarah lahan tempat berdirinya gedung tersebut: Bekas Rumah Tahanan (Penjara Gandhi).', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://maps.app.goo.gl/crwgW7BP3wpadDx3A', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_067_a.svg\",\"\\/images\\/sites\\/tjong_a_fie_interior.jpg\",\"\\/images\\/sites\\/site_067_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('68', '68', 'ARC-068', 'Kantor Siang Hwee (Kamar Dagang Tionghoa Deli)', 'Kantor Siang Hwee (Kamar Dagang Tionghoa Deli)', 'Bangunan Bersejarah', 'Kantor Organisasi Perdagangan', 'Situs', 'Coklat Kayu (Situs & Cagar Budaya)', '#78350F', '1907–1908', 'Kel. Kesawan, Kec. Medan Barat, Kota Medan, Sumatera Utara', 'Kesawan', 'Kec. Medan Barat', 'Kota Medan', '3.5872100', '98.6789400', 'Siang Hwee (Kamar Dagang Tionghoa) di wilayah Deli (Medan) mulai masif berkembang sejak pergerakan nasional sekira tahun 1907-1908, mengikuti pembentukan jaringan Siang Hwee pertama di Hindia Belanda. Organisasi ini didirikan sebagai wadah proteksi ekonomi sekaligus jembatan politik bagi para pedagang dan pengusaha Tionghoa di tanah Deli yang saat itu sedang mengalami booming komoditas perkebunan.', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://www.google.com/maps/search/?api=1&query=3.58721,98.67894', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_068_a.svg\",\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_068_b.svg\"]', '1', 'Data Situs Fix', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('69', '69', 'ARC-069', 'Taman Tjong Yong Hian (Tjong Yong Hian Gallery / Taman Kebun Bunga)', 'Taman Tjong Yong Hian (Tjong Yong Hian Gallery / Taman Kebun Bunga)', 'Taman & Ruang Publik', 'Taman Bersejarah & Situs Peninggalan Tokoh', 'Perkampungan', 'Hijau (Perkampungan & Ruang Hidup)', '#15803D', 'Abad ke-19 – ke-20', 'Jl. Kejaksaan, Medan Petisah', 'Petisah Tengah', 'Kec. Medan Petisah', 'Kota Medan', '3.5868962', '98.6693341', 'Menjadi peninggalan Tjong Yong Hian dan bukti hubungan harmonis berbagai agama dan budaya di Kota Medan.', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://maps.app.goo.gl/LoaTuMG3qtrfhucD6', '/images/sites/tokoh_tjong_yong_hian.jpg', '[\"\\/images\\/sites\\/tokoh_tjong_yong_hian.jpg\",\"\\/images\\/sites\\/site_069_a.svg\",\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_069_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('70', '70', 'ARC-070', 'Pajak Ikan Lama', 'Pajak Ikan Lama', 'Pusat Perdagangan Bersejarah', 'Pasar Tradisional Bersejarah', 'Situs', 'Coklat Kayu (Situs & Cagar Budaya)', '#78350F', '1890', 'HMQJ+38X, Jl. Stasiun Kereta Api, Kesawan, Kec. Medan Bar., Kota Medan, Sumatera Utara 20212', 'Kesawan', 'Kec. Medan Barat', 'Kota Medan', '3.5877492', '98.6808524', 'Didirikan oleh Tjong A Fie. Awalnya tempat penjualan ikan, daging, dan sayuran; kemudian berkembang menjadi pusat kain dan tekstil setelah kedatangan pedagang India, Arab, dan Singapura.', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://maps.app.goo.gl/qF5H5GX6C37L1QTY9', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_070_a.svg\",\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_070_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');
INSERT INTO `cultural_sites` (`id`, `marker_number`, `site_code`, `name`, `maps_name`, `category`, `sub_category`, `gallery_group`, `color_name`, `color_hex`, `year_period`, `address`, `desa_kelurahan`, `kecamatan`, `regency_city`, `latitude`, `longitude`, `uniqueness`, `source_name`, `source_url`, `gmaps_url`, `thumbnail`, `photos`, `is_featured_gallery`, `sheet_origin`, `created_at`, `updated_at`) VALUES ('71', '71', 'ARC-071', 'Eks Toko Seng Hap', 'Eks Toko Seng Hap', 'Pusat Perdagangan Bersejarah', 'Toko & Bangunan Komersial Bersejarah', 'Situs', 'Coklat Kayu (Situs & Cagar Budaya)', '#78350F', '1881', 'Jl. Jend. Ahmad Yani No.1, Kesawan, Kec. Medan Bar., Kota Medan, Sumatera Utara 20231', 'Kesawan', 'Kec. Medan Barat', 'Kota Medan', '3.5885239', '98.6783872', 'Didirikan oleh Tan Tang Ho. Seng Hap berarti “sukses” dan “kompak”. Bangunan awalnya berupa struktur kayu, pernah terbakar pada 1900, lalu sempat tutup dan terbengkalai pada 1970-an sebelum direvitalisasi.', 'Kajian Cagar Budaya & Ruang Kota', '', 'https://maps.app.goo.gl/pLG6UBR52EmVAC5EA', '/images/sites/kawasan_kesawan.jpg', '[\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_071_a.svg\",\"\\/images\\/sites\\/kawasan_kesawan.jpg\",\"\\/images\\/sites\\/site_071_b.svg\"]', '1', 'Data Situs Fix & DATA', '2026-11-12 12:52:33', '2026-11-12 12:52:33');

DROP TABLE IF EXISTS `documentary_videos`;
CREATE TABLE `documentary_videos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sort_order` int(11) NOT NULL DEFAULT 1,
  `code` varchar(24) NOT NULL,
  `title` varchar(255) NOT NULL,
  `location_subtitle` varchar(255) DEFAULT NULL,
  `category` varchar(100) NOT NULL DEFAULT 'Situs & Cagar Budaya',
  `youtube_id` varchar(32) NOT NULL,
  `youtube_url` varchar(255) NOT NULL,
  `embed_url` varchar(255) NOT NULL,
  `thumbnail` varchar(255) DEFAULT NULL,
  `duration` varchar(24) NOT NULL DEFAULT '05:00',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `documentary_videos_code_unique` (`code`),
  KEY `documentary_videos_sort_order_index` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

